-- Mois 6 (jours 151 à 180) du programme HABITUDES_DEFIS_30J_FR_V1, version 1 : remplace la reprise des 30 textes du mois 1.
-- Textes validés par Dr Justin Tshims le 28/10/2026 (« C'est bon », réponse à la relecture du mois 6). Généré depuis
-- editorial/habitudes-defis/mois-6-fr-relecture.md. Aucune inscription n'avait encore atteint le jour 151 : les textes
-- déjà servis (jours 1 à 150) ne changent pas. Activités, défis et horaires inchangés.
do $$begin
 if exists(select 1 from seneve.enrollments e where e.programme_id='HABITUDES_DEFIS_30J_FR_V1' and e.etat='active'
  and seneve.hd_date_du_jour(e.enrollment_id,151)<=(now()at time zone 'Africa/Kinshasa')::date)then
  raise exception 'Une inscription a déjà atteint le jour 151 : publier une nouvelle version plutôt que modifier celle-ci';
 end if;
 if (select count(*)from seneve.contents where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour between 151 and 180 and numero_message=1)<>30 then
  raise exception 'Jours 151 à 180 incomplets';
 end if;
end$$;
update seneve.contents set titre=$t$L'urgence fabriquée$t$,principe=$t$Reconnaître les voix qui pressent.$t$,theme=$t$Quelle voix te presse de décider vite en ce moment ?$t$,texte_officiel=$t$Le dernier chapitre du livre parle d'un piège discret : « l'urgence fabriquée ». Il en donne des exemples : « Décide maintenant ou tu rates le train. » « L'offre expire ce soir. » Ces phrases créent une pression qui empêche de prier et de réfléchir. Le livre résume : « L'urgence est la voix du monde. La paix est l'accent de Dieu. » Aujourd'hui, remarque une publicité, un message ou une conversation qui te presse de décider vite.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 134.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=151 and numero_message=1;
update seneve.contents set titre=$t$La voix la plus douce$t$,principe=$t$Faire de la place pour écouter.$t$,theme=$t$Quel bruit pourrais-tu réduire pour mieux écouter Dieu ?$t$,texte_officiel=$t$À Christian, qui dit que Dieu ne lui parle jamais, l'auteur répond : « Dieu n'a pas cessé de parler. C'est souvent nous qui avons cessé d'écouter ». Il ajoute : « La voix de Dieu n'est pas la voix la plus forte dans ta vie. C'est la plus douce — mais c'est aussi la plus vraie. » En plus du silence du matin, le livre propose une soirée sans écran, pour lire, prier et dormir en paix. Choisis un soir de cette semaine pour l'essayer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 135–136 ; annexe 1, page imprimée 156.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=152 and numero_message=1;
update seneve.contents set titre=$t$Le premier repère : la Parole$t$,principe=$t$Vérifier une impression à la lumière de la Bible.$t$,theme=$t$Quelle idée aimerais-tu examiner à la lumière de la Parole ?$t$,texte_officiel=$t$Christian demande comment savoir si une pensée vient de Dieu ou de ses propres envies. Le livre propose quatre repères. Le premier est la Parole écrite : « Toute direction divine sera cohérente avec la Bible. » Il ajoute que si une impression contredit l'Écriture, elle ne vient pas de Dieu. Pense à une idée qui te travaille en ce moment, et regarde avec honnêteté si elle s'accorde avec ce que la Bible enseigne.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 136–137.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=153 and numero_message=1;
update seneve.contents set titre=$t$La paix comme arbitre$t$,principe=$t$Laisser la paix intérieure guider une décision.$t$,theme=$t$Devant quelle décision la paix te manque-t-elle encore ?$t$,texte_officiel=$t$Le deuxième repère est la paix intérieure. Le livre cite : « Que la paix de Christ règne dans vos cœurs » (Colossiens 3:15), et explique que le mot grec signifie « arbitre ». Il en tire une image : « La paix est l'arbitre : si elle est absente, le match est suspendu. » La paix dont il parle n'est pas l'excitation du moment ; c'est un calme profond qui demeure. Devant une décision en cours, demande-toi si cette paix est là.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 137.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=154 and numero_message=1;
update seneve.contents set titre=$t$Ne pas décider seul$t$,principe=$t$Demander conseil avant une décision importante.$t$,theme=$t$À qui pourrais-tu demander conseil cette semaine ?$t$,texte_officiel=$t$Le livre ajoute deux repères : les circonstances qui convergent sans que tu les aies arrangées, et le conseil des sages. Il cite : « Les projets échouent faute de délibération, mais ils réussissent quand il y a de nombreux conseillers » (Proverbes 15:22). Il conclut : « Quand les quatre canaux s'alignent — avance avec assurance. Quand l'un d'eux résiste — attends encore. » Cette semaine, parle d'une décision difficile à un croyant mûr en qui tu as confiance.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 137.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=155 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : entendre la voix douce$t$,principe=$t$Faire le point sur l'écoute de Dieu.$t$,theme=$t$Quel moment d'écoute retiens-tu de cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de l'urgence fabriquée, de la voix douce de Dieu, de la Parole comme premier repère, de la paix comme arbitre et du conseil des sages. Relis tes déclarations sans te juger. Remarque un moment où tu as pris le temps d'écouter avant d'agir. Ce dernier mois t'invite à marcher avec Dieu, sans te presser.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 134–137 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=156 and numero_message=1;
update seneve.contents set titre=$t$Celui qui prie avant de signer$t$,principe=$t$Ne pas avoir honte de prendre le temps de prier.$t$,theme=$t$Dans quelle situation as-tu peur de paraître lent ?$t$,texte_officiel=$t$Le livre observe que l'urgence s'attaque à l'attente elle-même. Elle se moque de celui qui demande du temps : « Quoi, tu dois prier pour ça ? Tu n'es pas sérieux en affaires ! » Pourtant, écrit-il, « Tu ne peux pas tromper un homme qui prie avant de signer. » Prendre le temps de prier n'est pas un manque de sérieux. Si quelqu'un te presse aujourd'hui, tu as le droit de demander simplement un temps de réflexion.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 137–138.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=157 and numero_message=1;
update seneve.contents set titre=$t$L'Esprit relie$t$,principe=$t$Distinguer la voix qui isole de celle qui relie.$t$,theme=$t$Quelle décision gardes-tu pour toi alors qu'elle mériterait un conseil ?$t$,texte_officiel=$t$Le livre décrit une différence entre l'urgence et l'Esprit. L'urgence te pousse à décider seul, vite, sans en parler. L'Esprit, au contraire, t'invite à consulter, à vérifier et à confirmer. Quand on te demande de garder le secret sur une affaire pressée, c'est souvent un signal d'alerte. Aujourd'hui, si une décision te pèse, parles-en à une personne de confiance avant d'agir.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 138.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=158 and numero_message=1;
update seneve.contents set titre=$t$Un Dieu qui n'est jamais pressé$t$,principe=$t$Accepter le rythme de Dieu.$t$,theme=$t$Quelle attente te pèse le plus en ce moment ?$t$,texte_officiel=$t$Le livre écrit : « Dieu n'est jamais pressé. Ce qui vient de Dieu arrive dans la paix. » Il rappelle qu'Abraham a attendu Isaac vingt-cinq ans, que Moïse a été formé pendant quarante ans, et que Jésus s'est préparé trente ans pour trois ans de ministère. Il conclut : « Le Dieu de l'éternité ne connaît pas la panique. » Si une attente te pèse en ce moment, confie-la à Dieu et demande-Lui la patience.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 138.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=159 and numero_message=1;
update seneve.contents set titre=$t$Dormir dessus$t$,principe=$t$Se donner une nuit avant un engagement important.$t$,theme=$t$Quel engagement mérite au moins une nuit de réflexion ?$t$,texte_officiel=$t$L'auteur raconte qu'au début de son activité, il a signé des contrats importants « Sans prier suffisamment. Sans vérifier complètement. Sans dormir dessus. » Il en a tiré une règle : quand la pression de décider immédiatement est forte, c'est le signal de ralentir. Il écrit : « la lenteur sanctifiée m'a sauvé plus d'argent que toutes mes compétences réunies. » Prends aujourd'hui cette résolution : ne pas signer d'engagement important sans avoir prié et dormi dessus.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 139–140 et 148.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=160 and numero_message=1;
update seneve.contents set titre=$t$Une porte fermée n'est pas un échec$t$,principe=$t$Relire autrement une porte fermée.$t$,theme=$t$Quelle porte fermée aimerais-tu regarder autrement ?$t$,texte_officiel=$t$Paul voulait prêcher en Asie, puis en Bithynie ; l'Esprit l'en a empêché deux fois (Actes 16). Puis une vision l'a appelé en Macédoine, et l'Évangile est entré en Europe. Le livre écrit : « toutes les portes fermées ne sont pas des échecs. Certaines sont des protections. » Pense à une porte qui s'est fermée récemment : un poste, un visa, un projet. Remercie Dieu, même sans tout comprendre, et reste attentif à la suite.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 140–141.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=161 and numero_message=1;
update seneve.contents set titre=$t$Quand la paix manque$t$,principe=$t$Respecter une retenue intérieure.$t$,theme=$t$Quelle retenue intérieure as-tu tendance à ignorer ?$t$,texte_officiel=$t$Le livre raconte l'histoire d'un chef d'entreprise à qui l'on proposait un partenariat parfait sur le papier. Mais quelque chose le retenait : « Une absence de paix qu'il ne pouvait pas expliquer rationnellement. » Il a prié une semaine, puis il a refusé, malgré les critiques. Il a dit plus tard : « j'ai perdu un contrat. Mais j'ai gardé ma liberté. » Le livre ajoute : « Tu n'auras pas toujours des explications ». Respecte aujourd'hui une retenue que tu ressens.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 141–142.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=162 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : marcher sans courir$t$,principe=$t$Faire le point sur l'attente et le discernement.$t$,theme=$t$Quelle décision as-tu prise plus calmement cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de la prière avant de signer, de l'Esprit qui relie au lieu d'isoler, d'un Dieu jamais pressé, de la nuit de réflexion, des portes fermées et de la paix qui manque. Relis tes déclarations sans te juger. Remarque une décision que tu as prise plus calmement que d'habitude. Ralentir n'est pas perdre du temps : c'est marcher avec Dieu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 137–142 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=163 and numero_message=1;
update seneve.contents set titre=$t$Le Dieu qui connaît demain$t$,principe=$t$Se savoir conduit par l'Esprit.$t$,theme=$t$Pour quelle décision as-tu besoin de la conduite de l'Esprit ?$t$,texte_officiel=$t$Jésus promet : « Quand le Consolateur sera venu, l'Esprit de vérité, il vous conduira dans toute la vérité » (Jean 16:13). Le livre appelle cela « la plus belle des nouvelles : tu n'es pas seul pour décider. » Il ajoute : « Le Dieu qui connaît demain habite en toi et veut te guider aujourd'hui. » Aujourd'hui, avant de commencer ta journée, demande à l'Esprit de te conduire dans ce que tu as à faire.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 144.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=164 and numero_message=1;
update seneve.contents set titre=$t$Même dans ta cuisine$t$,principe=$t$Inviter l'Esprit dans les affaires ordinaires.$t$,theme=$t$Quelle affaire ordinaire croyais-tu trop petite pour Dieu ?$t$,texte_officiel=$t$Christian pensait que le Saint-Esprit, c'était surtout pour les réunions de prière. Le livre répond : « Il est pour ton bureau, pour ta cuisine, pour tes finances, pour ton mariage. » Il ajoute que l'Esprit s'intéresse aussi « à ton loyer, à ton commerce, à tes choix de quartier, à l'école de tes enfants ». Aujourd'hui, invite Dieu dans une affaire ordinaire que tu croyais trop petite pour Lui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 144.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=165 and numero_message=1;
update seneve.contents set titre=$t$Une question de trois secondes$t$,principe=$t$Prendre l'habitude de consulter Dieu avant d'agir.$t$,theme=$t$Avant quel choix de ta journée veux-tu poser cette question ?$t$,texte_officiel=$t$Le livre propose une discipline simple : avant chaque décision, même petite, se poser une question intérieure de trois secondes : « Seigneur, est-ce Ta direction ? » Il écrit : « Cette habitude transforme une vie. » Aujourd'hui, essaie de poser cette question avant tes choix de la journée : une réponse, un achat, une rencontre. Ce n'est pas une formule magique, mais une manière de garder ton cœur tourné vers Dieu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 144–145.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=166 and numero_message=1;
update seneve.contents set titre=$t$Les petites impressions$t$,principe=$t$Obéir aux petites invitations de l'Esprit.$t$,theme=$t$Quelle petite impression as-tu reçue récemment ?$t$,texte_officiel=$t$Le livre parle des petites impressions : la pensée de prier pour quelqu'un, une retenue avant un engagement. Il conseille d'y obéir, et ajoute : « Plus tu obéis aux petites voix, plus ton oreille s'affine pour les grandes directions. » Ces impressions restent à vérifier par la Parole, par la paix et par le conseil. Aujourd'hui, si la pensée te vient de prier pour quelqu'un ou de l'appeler, fais-le.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 145.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=167 and numero_message=1;
update seneve.contents set titre=$t$Marcher avec Lui$t$,principe=$t$Passer de la demande de miracles à la marche avec Dieu.$t$,theme=$t$Où aimerais-tu marcher avec Dieu plutôt que seulement Lui demander ?$t$,texte_officiel=$t$À la fin de sa conversation avec l'auteur, Christian reste silencieux, puis dit : « je ne mendiais pas des directions. Je mendiais des miracles. Et Dieu voulait juste que je marche avec Lui. » Le livre précise que son titre est né de dizaines de conversations comme celle-là. Aujourd'hui, au lieu de demander seulement une solution, demande à Dieu de marcher avec toi dans ta journée.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 145.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=168 and numero_message=1;
update seneve.contents set titre=$t$Une nuit de prière$t$,principe=$t$Prendre le temps de prier avant un choix important.$t$,theme=$t$Quel choix important mérite un temps de prière plus long ?$t$,texte_officiel=$t$Le livre remarque qu'on ne trouve dans les Évangiles aucune scène où Jésus se précipite. Avant de choisir les Douze, « Il passa toute la nuit à prier Dieu » (Luc 6:12). Une nuit entière, pour une décision qui allait compter pendant des siècles. Tu n'as pas forcément besoin d'une nuit entière. Mais pour un choix important, prévois un vrai temps de prière, plus long que d'habitude.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 145.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=169 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la conduite au quotidien$t$,principe=$t$Faire le point sur la conduite de l'Esprit.$t$,theme=$t$Quand as-tu consulté Dieu avant d'agir cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de l'Esprit qui conduit, de Dieu présent jusque dans la cuisine, de la question de trois secondes, des petites impressions, de la marche avec Dieu et de la nuit de prière de Jésus. Relis tes déclarations sans te juger. Remarque un moment où tu as consulté Dieu avant d'agir. C'est ainsi que l'oreille s'affine, jour après jour.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 144–145 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=170 and numero_message=1;
update seneve.contents set titre=$t$Deux jours de plus$t$,principe=$t$Garder confiance quand Dieu semble tarder.$t$,theme=$t$Dans quelle situation Dieu semble-t-Il tarder pour toi ?$t$,texte_officiel=$t$Quand on annonce à Jésus que Lazare est malade, l'Évangile note : « Il resta encore deux jours dans le lieu où Il était » (Jean 11:6). Autour de Lui, tout le monde comptait les heures. Le livre conclut : « Voilà ton Roi : jamais en retard, jamais pressé, jamais poussé. » Si Dieu semble tarder dans une situation, confie-Lui ton inquiétude et continue de marcher avec Lui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, page imprimée 146.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=171 and numero_message=1;
update seneve.contents set titre=$t$La peur de rater$t$,principe=$t$Ne plus être gouverné par la peur de rater.$t$,theme=$t$Quelle occasion as-tu peur de rater en ce moment ?$t$,texte_officiel=$t$L'auteur reconnaît qu'il signait vite « parce que j'avais peur de rater ». Il appelle cette peur « l'arme principale de l'urgence ». La prière du chapitre 7 dit : « Je renonce à être gouverné par la peur de rater. » Repère aujourd'hui une décision que la peur de manquer une occasion te pousse à prendre. Puis prie avec ces mots, ou avec les tiens.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 139 et 147.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=172 and numero_message=1;
update seneve.contents set titre=$t$Une clé dans la poche$t$,principe=$t$Choisir une clé à vivre.$t$,theme=$t$Quelle clé est restée dans ta poche ?$t$,texte_officiel=$t$La conclusion du livre rappelle les sept clés : Dieu d'abord, la dîme et l'offrande, le travail intègre, la liberté face à l'argent, la Tsedaka, la fidélité dans le peu et la conduite de l'Esprit. Puis elle ajoute : « une clé qui reste dans la poche n'a jamais ouvert une porte. » Ces six mois t'ont fait traverser toutes ces clés. Laquelle est restée dans ta poche ? Choisis-en une à vivre concrètement cette semaine.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, pages imprimées 149–150.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=173 and numero_message=1;
update seneve.contents set titre=$t$Qui gouverne ta vie ?$t$,principe=$t$Répondre honnêtement à la grande question.$t$,theme=$t$Qui gouverne réellement ta vie aujourd'hui ?$t$,texte_officiel=$t$À la fin du livre, l'auteur repose la question du début : « Qui gouverne réellement ta vie ? » Il précise : « Pas en théorie. Pas dans tes confessions du dimanche. » La réponse se trouve dans les choix concrets : l'argent, les décisions, la main tendue ou fermée. Il écrit que c'est « dans l'ordinaire invisible » que le Royaume est réel. Prends un moment pour répondre à cette question devant Dieu, sans te juger.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, page imprimée 150.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=174 and numero_message=1;
update seneve.contents set titre=$t$Des gens obéissants$t$,principe=$t$Se rappeler que Dieu honore l'obéissance simple.$t$,theme=$t$Quelle obéissance simple peux-tu vivre aujourd'hui ?$t$,texte_officiel=$t$La conclusion redit une phrase du chapitre 1 : « Dieu ne cherche pas des gens parfaits ni brillants. Il cherche des gens obéissants. » Elle évoque l'obéissance d'une vendeuse de beignets ou d'un agent de sécurité, dont tu as lu les histoires au long de ce parcours. Puis elle ajoute : « La tienne peut commencer aujourd'hui. » Ton histoire n'a pas besoin d'être spectaculaire. Elle peut être faite d'obéissances simples, répétées.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, pages imprimées 150–151.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=175 and numero_message=1;
update seneve.contents set titre=$t$Dans un an$t$,principe=$t$Regarder le chemin sur la durée.$t$,theme=$t$Qu'est-ce qui a déjà commencé à changer en toi ?$t$,texte_officiel=$t$Le livre invite à avancer clé après clé. Il écrit que, dans un an, la vie peut être méconnaissable, « non que tes circonstances auront magiquement changé, mais parce que la personne au centre de ces circonstances aura changé. » Il ne promet pas que tout ira autrement autour de toi ; il parle d'un changement intérieur. Pense à la personne que tu deviens, et demande à Dieu de continuer Son œuvre en toi.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, page imprimée 151.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=176 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la clé à vivre$t$,principe=$t$Faire le point avant la fin du parcours.$t$,theme=$t$Quelle clé t'a le plus parlé ces dernières semaines ?$t$,texte_officiel=$t$Cette semaine a parlé de Jésus qui ne se presse pas, de la peur de rater, des sept clés, de la question de qui gouverne ta vie, de l'obéissance simple et du changement intérieur. Relis tes déclarations sans te juger. Ce parcours touche à sa fin. Remarque la clé qui t'a le plus parlé ces dernières semaines.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 146–147 ; conclusion générale, pages imprimées 149–151 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=177 and numero_message=1;
update seneve.contents set titre=$t$Jeter son manteau$t$,principe=$t$Laisser derrière soi ses habitudes de mendiant.$t$,theme=$t$Quel manteau aimerais-tu laisser au bord du chemin ?$t$,texte_officiel=$t$Le livre se termine avec Bartimée, l'aveugle qui mendiait au bord du chemin de Jéricho. Quand Jésus l'appelle, l'Évangile note : « Il jeta son manteau, se leva d'un bond, et vint vers Jésus » (Marc 10:50). Le livre explique que ce manteau était l'outil de son métier de mendiant, et qu'« un homme qui court vers le Roi n'a plus besoin de son costume de mendiant. » Pense à une vieille habitude que tu aimerais laisser derrière toi.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, pages imprimées 152–153.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=178 and numero_message=1;
update seneve.contents set titre=$t$Suivre le Roi sur le chemin$t$,principe=$t$Passer de la main tendue au cœur ouvert.$t$,theme=$t$Que veux-tu dire à Dieu en arrivant au bout de ce chemin ?$t$,texte_officiel=$t$Après sa guérison, Bartimée « suivit Jésus dans le chemin ». Il ne retourna pas chercher son manteau. La prière finale du livre dit : « Je ne viens plus vers Toi la main tendue — je viens vers Toi le cœur ouvert, pour Te suivre sur le chemin. » Et le livre se termine ainsi : « Arrête de mendier des miracles. Jette ton manteau. Et suis le Roi sur le chemin. » Aujourd'hui, prie avec ces mots, ou avec les tiens.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, pages imprimées 153–154.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=179 and numero_message=1;
update seneve.contents set titre=$t$Une lettre à Dieu$t$,principe=$t$Faire le bilan paisible des six mois.$t$,theme=$t$Que veux-tu écrire à Dieu au terme de ces six mois ?$t$,texte_officiel=$t$Ce parcours de six mois arrive à son terme. L'annexe du livre propose, pour finir, d'écrire une lettre à Dieu : « pas une prière formelle, mais une conversation honnête » sur ce que ce temps t'a appris et sur ce que tu veux poursuivre. Relis tes bilans de mois, sans chercher de note. Ton bilan ne mesure ni ta foi ni ta valeur. Les habitudes que tu as prises peuvent continuer bien au-delà de ce parcours.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, annexe 1, page imprimée 159.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=180 and numero_message=1;
update seneve.programme_versions set valide_par=valide_par||' ; mois 6 (jours 151 à 180) validé le 28/10/2026'
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and valide_par not like '%mois 6%';
